('fccb1c12-a71f-5c0b-b138-f9a156b07dc6','citizen-land-hand-sim','demo','Chuyển nhượng đất — mô phỏng điền tay','Hợp đồng chuyển nhượng quyền sử dụng đất',NULL,'needs_review','Thông tin giả lập; chữ viết bằng font, không phải nét viết tay của người thật. Không dùng để kết luận chất lượng OCR chữ viết tay thực tế.','{"sample_kind": "synthetic_handwriting_font", "dataset": "citizen-forms-v1", "conversion": "Điền font Patrick Hand vào form dẫn xuất; raster 170 DPI, không lớp text", "parent_document_id": "citizen-land-contract", "source_page_url": "https://www.congchung6.gov.vn/vi/document/bieu-mau-216.aspx", "test_expectation_not_ocr": {"expected_type_id": "U15-D14", "expected_fields": {"Bên chuyển nhượng": "Nguyễn Văn An", "Bên nhận chuyển nhượng": "Lê Văn Bình", "Số thửa đất": "128", "Số tờ bản đồ": "09", "Diện tích đất": "120,5 m²", "Số giấy chứng nhận": "TEST-GCN-001", "Giá chuyển nhượng": "850.000.000 đồng"}, "purpose": "Ground truth giả lập để đối chiếu; tuyệt đối không đưa vào đầu vào model hoặc giả làm kết quả OCR."}}'::jsonb),
('b0696669-b560-5771-aeb1-61d3bc1f4371','citizen-inheritance-hand-sim','demo','Thừa kế — mô phỏng điền tay quan hệ nhân thân','Tờ tường trình về quan hệ nhân thân',NULL,'needs_review','Thông tin giả lập; chữ viết bằng font, không phải nét viết tay của người thật. Không dùng để kết luận chất lượng OCR chữ viết tay thực tế.','{"sample_kind": "synthetic_handwriting_font", "dataset": "citizen-forms-v1", "conversion": "Điền font Patrick Hand vào form dẫn xuất; raster 170 DPI, không lớp text", "parent_document_id": "citizen-inheritance-kinship", "source_page_url": "https://www.congchung6.gov.vn/vi/document/bieu-mau-216.aspx", "test_expectation_not_ocr": {"expected_type_id": "U09-D12", "expected_fields": {"Người tường trình": "Nguyễn Thị Mai", "Người để lại di sản": "Nguyễn Văn An", "Ngày mất": "15/02/2025", "Quan hệ với người để lại di sản": "con", "Vợ hoặc chồng người để lại di sản": "", "Các con của người để lại di sản": "Nguyễn Thị Mai; Nguyễn Văn Minh"}, "purpose": "Ground truth giả lập để đối chiếu; tuyệt đối không đưa vào đầu vào model hoặc giả làm kết quả OCR.", "note": "Mẫu để trống mục vợ/chồng; không suy ra kết hôn từ việc có chung con."}}'::jsonb),
